import { WORKBENCH_CSS } from "../workbench/styles";
import { HOME_CSS } from "../workbench/dashboard-home";
import { DASHBOARD_CSS } from "../../../dashboard/src/view";
import { mountStaticClientStyle } from "../../../dashboard/src/client-style

// Native plugin styles have an explicit owner and lifetime. Do not depend
// on resource tags rendered inside the replaceable root slot.
if (typeof document !== "undefined") {
  for (const [name, css] of [["workbench.css", WORKBENCH_CSS], ["home.css", HOME_CSS], ["dashboard.css", DASHBOARD_CSS]] as const) {
    ctx.effect(() => mountStaticClientStyle(document, "@dsh-spaces/plugin", name, css));
  }
}

const appearance = await app.locator('.dsh-workbench').evaluate(root => ({
    display: getComputedStyle(root).display,
    overflow: getComputedStyle(root).overflow,
    railWidth: root.querySelector('.dsh-wb-rail').getBoundingClientRect().width,
    grid: getComputedStyle(root.querySelector('.dd-grid')).display,
    ownedSheets: [...document.querySelectorAll('style[data-plugin="@dsh-spaces/plugin"]')].map(tag => ({
      name: tag.getAttribute('data-plugin-css'), active: !!tag.sheet && tag.sheet.cssRules.length > 0,
    })),
  }));
  assert.equal(appearance.display, 'flex', 'Actual native workbench stylesheet must apply');
  assert.equal(appearance.overflow, 'hidden');
  assert.ok(appearance.railWidth > 40 && appearance.railWidth < 200);
  assert.equal(appearance.grid, 'grid');
  assert.equal(appearance.ownedSheets.length, 3); assert.ok(appearance.ownedSheets.every(sheet => sheet.active));

import { mountStaticClientStyle } from '../packages/dashboard/src/client-style.ts';

test('native static stylesheet ownership and cleanup never replace another plugin sheet', () => {
  const nodes: any[] = [];
  const fake = { createElement: (name: string) => {
    assert.equal(name, 'style');
    const node = { dataset: {} as Record<string, string>, textContent: '', remove: () => {
      const at = nodes.indexOf(node); if (at >= 0) nodes.splice(at, 1);
    } }; return node;
  }, head: { appendChild: (node: unknown) => nodes.push(node) } } as unknown as Document;
  const foreign = { foreign: true }; nodes.push(foreign);
  const remove = mountStaticClientStyle(fake, '@dsh-spaces/plugin', 'workbench.css', '.dsh-workbench{display:flex}');
  const second = mountStaticClientStyle(fake, '@dsh-spaces/dashboard', 'dashboard.css', '.dsh-dashboard{display:block}');
  assert.equal(nodes.length, 3);
  assert.equal(nodes[1].dataset.plugin, '@dsh-spaces/plugin');
  assert.equal(nodes[1].dataset.pluginCss, '@dsh-spaces/plugin/workbench.css');
  assert.equal(nodes[1].textContent, '.dsh-workbench{display:flex}');
  remove(); remove(); assert.equal(nodes.length, 2); assert.strictEqual(nodes[0], foreign);
  second(); assert.deepEqual(nodes, [foreign]);
});
